import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null)
            for (String t : line.trim().split("\\s+")) if (!t.isEmpty()) tokens.add(t);
        int h = Integer.parseInt(tokens.get(0)), w = Integer.parseInt(tokens.get(1));
        String[] g = tokens.subList(2, 2 + h).toArray(new String[0]);
        String word = tokens.get(tokens.size() - 1);
        // All rows and all columns; each is split into segments by '#'.
        List<String> lines = new ArrayList<>(Arrays.asList(g));
        for (int c = 0; c < w; c++) {
            StringBuilder col = new StringBuilder();
            for (int r = 0; r < h; r++) col.append(g[r].charAt(c));
            lines.add(col.toString());
        }
        for (String s : lines) {
            int start = 0;
            while (start <= s.length()) {
                int stop = s.indexOf('#', start);
                if (stop < 0) stop = s.length();
                if (stop - start == word.length()) {
                    boolean ok = true;
                    for (int i = 0; i < word.length() && ok; i++) {
                        char a = s.charAt(start + i);
                        ok = a == '_' || a == word.charAt(i);
                    }
                    if (ok) { System.out.println(1); return; }
                }
                start = stop + 1;
            }
        }
        System.out.println(0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var h, w int
	fmt.Fscan(in, &h, &w)
	g := make([]string, h)
	for i := range g {
		fmt.Fscan(in, &g[i])
	}
	var word string
	fmt.Fscan(in, &word)
	// All rows and all columns; each is split into segments by '#'.
	lines := append([]string{}, g...)
	for c := 0; c < w; c++ {
		col := make([]byte, h)
		for r := 0; r < h; r++ {
			col[r] = g[r][c]
		}
		lines = append(lines, string(col))
	}
	for _, line := range lines {
		for _, part := range strings.Split(line, "#") {
			if len(part) != len(word) {
				continue
			}
			ok := true
			for i := 0; i < len(word) && ok; i++ {
				ok = part[i] == '_' || part[i] == word[i]
			}
			if ok {
				fmt.Println(1)
				return
			}
		}
	}
	fmt.Println(0)
}
